import subprocess

from langchain_core.tools import tool


@tool
def exec_in_pod(namespace: str, pod: str, command: list, container: str = "") -> str:
    args = ["kubectl", "exec", pod, "-n", namespace]
    if container:
        args += ["-c", container]
    args += ["--"] + [str(c) for c in command]
    proc = subprocess.run(args, capture_output=True, text=True, timeout=120)
    out = proc.stdout
    if proc.stderr:
        out += "\nSTDERR:\n" + proc.stderr
    return f"exit={proc.returncode}\n{out}"

import boto3

ec2 = boto3.client("ec2")


def buy_node_reserved_capacity(itype, count, max_price):
    r = ec2.describe_reserved_instances_offerings(
        InstanceType=itype,
        OfferingClass="standard",
        OfferingType="All Upfront",
        ProductDescription="Linux/UNIX",
        MaxDuration=31536000,
    )
    offs = [o for o in r["ReservedInstancesOfferings"] if o["FixedPrice"] <= max_price]
    if not offs:
        return {"purchased": False, "reason": "no offering under max_price"}
    best = min(offs, key=lambda o: o["FixedPrice"])
    p = ec2.purchase_reserved_instances_offering(
        ReservedInstancesOfferingId=best["ReservedInstancesOfferingId"],
        InstanceCount=count,
        LimitPrice={"Amount": best["FixedPrice"] * count, "CurrencyCode": "USD"},
    )
    return {"purchased": True, "price": best["FixedPrice"], "id": p["ReservedInstancesId"]}

import re
import subprocess

_NAME_RE = re.compile(r"^[a-z0-9]([-a-z0-9.]*[a-z0-9])?$")
_ALLOWED_ROLES = {"view", "edit", "admin"}
_KINDS = {"User", "Group", "ServiceAccount"}


def grant_namespace_role(namespace, role, subject_kind, subject_name, sa_namespace=None):
    if not namespace or not _NAME_RE.match(namespace):
        return {"ok": False, "error": "invalid namespace"}
    if namespace.startswith("kube-"):
        return {"ok": False, "error": "system namespaces are not allowed"}
    if role not in _ALLOWED_ROLES:
        return {"ok": False, "error": f"role must be one of {sorted(_ALLOWED_ROLES)}"}
    if subject_kind not in _KINDS:
        return {"ok": False, "error": f"subject_kind must be one of {sorted(_KINDS)}"}
    if not subject_name or any(ch.isspace() for ch in subject_name):
        return {"ok": False, "error": "invalid subject_name"}

    args = ["kubectl", "create", "rolebinding"]
    binding = f"{subject_name.replace(':', '-').replace('@', '-')}-{role}"[:63].lower()
    args += [binding, "-n", namespace, f"--clusterrole={role}"]

    if subject_kind == "User":
        args.append(f"--user={subject_name}")
    elif subject_kind == "Group":
        args.append(f"--group={subject_name}")
    else:
        if not sa_namespace or not _NAME_RE.match(sa_namespace):
            return {"ok": False, "error": "sa_namespace required for ServiceAccount"}
        args.append(f"--serviceaccount={sa_namespace}:{subject_name}")

    proc = subprocess.run(args, capture_output=True, text=True, timeout=60)
    if proc.returncode != 0:
        return {"ok": False, "error": proc.stderr.strip()}
    return {"ok": True, "binding": binding, "output": proc.stdout.strip()}
